export const SEED_DRILLS = [

  // ── PASSING (15) ──────────────────────────────────────────────────────────
  { id:1,  title:"Rondo Passing Circle",         category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"8-12",               home_ready:false, diagram:"rondo",    description:"Players form a circle with 2 defenders in the middle. Outside players keep possession using quick one and two-touch passes. Defenders try to intercept. Rotate defenders every 90 seconds.", coach_notes:"Emphasise eye contact before the pass. Encourage movement after passing — don't stand still." , progression:"Reduce the circle size to increase pressure. Add a third defender. Limit to one touch only." },
  { id:2,  title:"Wall Passes",                  category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"wall",     description:"Have your child pass the ball against a wall and control the rebound. Vary the distance and angle of the passes to work on both short and long passes. Try to use both feet equally.", coach_notes:"Vary the weight and angle each session. Encourage players to control with their weaker foot too." , progression:"Increase the distance from the wall. Add a second touch — control then pass. Use weaker foot only." },
  { id:3,  title:"Triangle Passing",             category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"6-9",                home_ready:false, diagram:"triangle", description:"3 players stand in a triangle 8m apart. Pass and move to a different point each time. Progression: add a defender in the middle.", coach_notes:"Encourage open body shape — receive across the body so you can see the next pass before it arrives." , progression:"Reduce to one touch. Add two defenders in the middle. Increase triangle size and add movement." },
  { id:4,  title:"Target Passing",               category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"targetpass",    description:"Set up targets such as small goals or markers at various distances around the garden. Challenge your child to pass the ball accurately to hit each target — accuracy over power.", coach_notes:"Encourage players to record how many out of 10 they hit and try to beat their score next time." , progression:"Increase distance between targets. Add a defender who tries to intercept. Use weaker foot only." },
  { id:5,  title:"4-Goal Possession",            category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"10-14",              home_ready:false, diagram:"rondo",    description:"4v4 in a 25x25m grid with 4 small goals. Teams score by passing through any goal. Encourages switching play and scanning.", coach_notes:"Praise players who switch play quickly. Stop the game to show what opening up looks like." , progression:"Add a rule that players must complete 5 passes before scoring. Reduce grid size." },
  { id:6,  title:"One-Touch Passing Line",       category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"8+",                 home_ready:false, diagram:"triangle",     description:"Two lines face each other 6m apart. Player passes, then runs to the back of the opposite line. One touch only. Build pace over time.", coach_notes:"Feet ready before the ball arrives. First touch mindset — get the body behind the ball early." , progression:"Increase pace — no standing still. Add a defender in the middle to intercept." },
  { id:7,  title:"Switch & Drive",               category:"Passing", age_groups:["U13","U14"],       duration:"10 min", players:"8-12",               home_ready:false, diagram:"switch",   description:"In a 40m wide channel, players must switch the ball across the pitch in 3 passes or fewer before a player drives forward.", coach_notes:"Builds width awareness. Praise players who look for the switch even under pressure." , progression:"Add a time limit — must switch in 2 passes. Add a pressing defender." },
  { id:8,  title:"Passing Square",               category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"4-8",                home_ready:false, diagram:"triangle",   description:"4 cones form a 10x10m square. Players rotate passing clockwise then anti-clockwise. Vary pace and add a directional change on coach signal.", coach_notes:"Encourage body orientation — don't always face the same direction. Scan before receiving." , progression:"One touch only. Add directional instructions — player must pass in the direction called by coach." },
  { id:9,  title:"Blind Side Pass",              category:"Passing", age_groups:["U13","U14"],       duration:"10 min", players:"6-10",               home_ready:false, diagram:"triangle",    description:"Attackers use a decoy run to create a blind side, then play a layoff pass to a runner. Defenders attempt to track. Rotate roles every 3 minutes.", coach_notes:"The communication before the pass is as important as the pass itself. Verbal cue first." , progression:"Add an active defender who tries to intercept the layoff. Reduce the space available." },
  { id:10, title:"Progressive Passing Lanes",    category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"8-14",               home_ready:false, diagram:"lanes",    description:"Divide the pitch into 3 vertical lanes. Team must pass into each lane before shooting. Builds progressive build-up play.", coach_notes:"Reward patience. Teams that rush into shooting without using all 3 lanes restart possession." , progression:"Add a time limit per zone. Introduce a defender in each lane." },
  { id:11, title:"Combination Play — Give & Go", category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"6-10",               home_ready:false, diagram:"triangle",    description:"Player passes to a teammate and immediately sprints to receive it back in a new position. Work in groups of 3 across a 20m channel. Rotate roles every 5 reps.", coach_notes:"The sprint after the pass is the skill — many players stand and watch. Reward the run." , progression:"Add light contact. Progress to full 1v1 with a goal to defend." },
  { id:12, title:"Long Diagonal Switching",      category:"Passing", age_groups:["U13","U14","U15"], duration:"10 min", players:"8-14",               home_ready:false, diagram:"switch",   description:"Full width pitch setup. Players work in pairs on opposite flanks switching the ball diagonally across the pitch using driven passes. Must land within 2m of partner.", coach_notes:"Technique focus — locked ankle, follow through toward the target. Don't sacrifice accuracy for power." , progression:"Reduce the channel width. Add a second attacker so defender must choose who to track." },
  { id:13, title:"Receive & Turn",               category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"Pairs",              home_ready:false, diagram:"wall", description:"Player A plays a firm pass to Player B who has their back to goal. Player B must control and turn in one movement before playing the ball through a gate. Rotate every 8 reps.", coach_notes:"Half turn on receiving — open body before the ball arrives. This is a key U12-U14 skill." , progression:"Add a second defender. Reduce box size to increase pressure." },
  { id:14, title:"3v1 Keep Ball",                category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"8-12",               home_ready:false, diagram:"triangle",    description:"3 attackers keep the ball from 1 defender in an 8x8m square. 10 consecutive passes = 1 point. Defender rotates on interception or after 30 seconds.", coach_notes:"Quick feet, quick decisions. Encourage support angles — never stand behind the ball." , progression:"Reduce the time to win the ball to 7 seconds. Add a fourth attacker." },
  { id:15, title:"Passing Under Pressure",       category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"6-10",               home_ready:false, diagram:"channel",    description:"Pairs pass through 5 gates in a 20x20m area while 2 defenders try to intercept. Score 1 point per gate. Swap defenders every 2 minutes.", coach_notes:"Decision-making under pressure. Encourage quick scanning before receiving — know your next pass before the ball arrives." , progression:"Progress to moving shadow — both players jogging. Then add light contact." },

  // ── TACKLING & DEFENDING (15) ─────────────────────────────────────────────
  { id:16, title:"Shadow Tackle Drill",          category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"recovery",     description:"Players work in pairs. One dribbles slowly, the other mirrors their movement practising stance and timing without contact. Progress to controlled contact on coach signal.", coach_notes:"Correct body shape first — side-on approach, low stance, eyes on ball not player." , progression:"Shorten the head start. Add a second attacker to create a 2v1 after the sprint." },
  { id:17, title:"Jockeying Channel",            category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"press",     description:"Set a 5m wide, 15m long channel. Attacker dribbles to end line; defender jockeys without tackling for first 10m, then can attempt to win the ball.", coach_notes:"Goal is to delay, not win the ball immediately. Patience is the skill — reward defenders who stay on their feet." , progression:"Add a second attacking unit pressing at the same time. Introduce specific press triggers." },
  { id:18, title:"1v1 Tackle Box",               category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"tackle",     description:"8x8m box. Attacker attempts to dribble out any side; defender attempts a clean tackle. Swap every 60 seconds. First to 5 wins.", coach_notes:"Tackle timing: wait for the attacker's heavy touch. Don't commit early — patience wins." , progression:"Progress to live 1v1 situations. Introduce timing — only slide when opponent takes heavy touch." },
  { id:19, title:"Press & Win",                  category:"Tackling", age_groups:["U12","U13","U14"], duration:"10 min", players:"6-10",              home_ready:false, diagram:"channel",      description:"3 attackers play out from the back; 3 defenders press as a unit to win the ball within 10 seconds. Reset and repeat.", coach_notes:"The trigger to press is key. Agree on the signal before the drill starts — a back pass or goalkeeper touch." , progression:"Increase the number of attackers to 3v2. Add a time limit to force quicker decisions." },
  { id:20, title:"Channelling to Safety",        category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"tackle",    description:"Defender steers attacker toward the touchline using body shape alone — no tackle. Attacker tries to cut back inside. Switch roles every 90 seconds.", coach_notes:"Arms out, stay patient, guide them wide. Reward defenders who succeed without diving in." , progression:"Add light contact. Progress to full 1v1 where defender can attempt a tackle." },
  { id:21, title:"Recovery Run & Defend",        category:"Tackling", age_groups:["U13","U14"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"defshape",   description:"Defender starts 5m behind attacker. On signal, both sprint 20m. Defender must recover and use body shape to delay — no wild lunge.", coach_notes:"Recover to the inside of the attacker, not directly at the ball. Control the angle, don't dive in." , progression:"Remove the pass requirement — attackers can shoot immediately. Reduce to 3v3." },
  { id:22, title:"Team Defensive Shape",         category:"Tackling", age_groups:["U13","U14","U15"], duration:"10 min", players:"Full squad",        home_ready:false, diagram:"defshape",   description:"Full defensive unit pressed by an attacking team. Coach freeze-coaches to correct shape, compactness, and press triggers.", coach_notes:"Pause when shape is poor, ask players to identify the problem before you correct it." , progression:"Introduce a second defender. Vary the cross height — driven, lofted, pulled back." },
  { id:23, title:"Intercept or Hold",            category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"6-10",              home_ready:false, diagram:"channel",  description:"Midfield scenario: 2 attackers + goalkeeper vs 2 defenders. Defenders decide whether to intercept the pass or hold their line. Discuss choices after each rep.", coach_notes:"No right answer every time — the decision-making is the skill. Reward the right choice, not just the successful one." , progression:"Reduce the channel width. Give the defender a head start from behind." },
  { id:24, title:"Defensive Line Work",          category:"Tackling", age_groups:["U13","U14","U15"], duration:"10 min", players:"Full squad",        home_ready:false, diagram:"press",   description:"Back 4 practise holding a defensive line — stepping up together on coach signal, dropping on signal. Introduce offside trap once movement is coordinated.", coach_notes:"Communication is everything — nominate a leader to call the line. Everyone moves on the same voice." , progression:"Reduce the number of attackers to 3v2. Add a time limit of 8 seconds." },
  { id:25, title:"2v2 Defending",                category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"8-12",              home_ready:false, diagram:"defshape",     description:"2v2 in a 15x10m channel. Defenders work together to win the ball — one applies pressure, one covers. Rotate pairs every 2 minutes.", coach_notes:"The covering defender's angle is key — not too close, not too far. They should be able to see both the ball and their attacker." , progression:"Add a second defender who tracks the overlapping run. Vary the timing of the overlap." },
  { id:26, title:"Press Triggers Training",      category:"Tackling", age_groups:["U13","U14","U15"], duration:"10 min", players:"Full squad",        home_ready:false, diagram:"jockey",      description:"Walk through 3 pre-agreed press triggers as a team (back pass, poor first touch, sideways pass). Practise recognising the trigger and pressing as a unit.", coach_notes:"Slow walk-through first. The whole team must agree on the trigger — if one player doesn't press, the shape breaks." , progression:"Reduce the time limit to 1.5 seconds. Add a second defender closing from a different angle." },
  { id:27, title:"Tackle Timing Gates",          category:"Tackling", age_groups:["U12","U13","U14"], duration:"10 min", players:"Pairs",             home_ready:false, diagram:"defshape",    description:"Attacker dribbles through a 10m channel toward a gate. Defender must choose the right moment to attempt a tackle — too early or too late and the attacker scores.", coach_notes:"Teach patience — the correct moment is when the attacker takes a heavy touch. Count the successes not the attempts." , progression:"Make both defenders active from the start. Add a time limit for the combination." },
  { id:28, title:"Compact Defending Shape",      category:"Tackling", age_groups:["U13","U14","U15"], duration:"10 min", players:"Full squad",        home_ready:false, diagram:"tackle",   description:"Team practises staying compact defensively — two banks maintaining 15m between lines. Ball moved around by attackers; team shifts as a unit.", coach_notes:"Show visually what compact looks like vs a stretched team. Use cones to mark the ideal distances between lines." , progression:"Increase the pace of the service. Mix in aerial balls that require a headed or chested first touch." },
  { id:29, title:"Slide Tackle Technique",       category:"Tackling", age_groups:["U13","U14"],       duration:"10 min", players:"Any",               home_ready:false, diagram:"recovery",      description:"Soft ground only. Players practise sliding on their non-dominant hip, leading with the stronger foot. Technique must be clean before adding any opposition.", coach_notes:"Only at U13+. Emphasise it's a last resort — show examples of poorly timed slide tackles as a deterrent." , progression:"Make both defenders active immediately. Add a second defender tracking the run." },
  { id:30, title:"Goalkeeper Distribution",      category:"Goalkeeping", age_groups:["U12","U13","U14"], duration:"10 min", players:"Any",               home_ready:false, diagram:"gkhandling",         description:"Goalkeeper practises distribution from hands and ground. Throw to target players in wide areas, then driven passes on the ground. Defenders must retreat 10 yards — retreat line rule applies.", coach_notes:"At U12/13 the retreat line means opposition must be 10 yards away. Encourage the GK to look up before distributing — don't just boot it." , progression:"Add active defenders to the set piece. Vary the delivery point — near post, far post, short." },

  // ── ATTACKING & FINISHING (15) ────────────────────────────────────────────
  { id:31, title:"3v2 Attacking Overload",       category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"10-15",             home_ready:false, diagram:"3v2",        description:"3 attackers vs 2 defenders + goalkeeper in a 20x15m grid. Must complete 3 passes before shooting. Rotate roles every 5 minutes.", coach_notes:"Encourage the third man run. The player without the ball should always be creating space." , progression:"Reduce the passes required to 2 before shooting. Add a time limit -- attackers must score within 8 seconds of winning possession." },
  { id:32, title:"Finishing From Crosses",       category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"6-12",              home_ready:false, diagram:"cross",       description:"Wide player delivers from the flank. 2 attackers make near and far post runs. Vary the delivery — early, pulled back, driven.", coach_notes:"Run timing is more important than finish quality at this age. Reward well-timed runs even if the finish is poor." , progression:"Increase speed between sets. Add a ball — dribble out of each gate rather than just passing." },
  { id:33, title:"Spot Shooting",                category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent",home_ready:true, diagram:"shootpress",   description:"Mark different spots around your garden. Take shots from each spot aiming for a specific part of the goal or target. Improves shooting accuracy from different angles and distances. Score yourself out of 10 per spot.", coach_notes:"Vary where they aim — corners not just the middle. Encourage players to track their scores and beat them next session." , progression:"Reduce the coach's arm-drop signal — use a smaller movement to make the reaction harder." },
  { id:34, title:"Counter Attack Sprint",        category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"8-14",              home_ready:false, diagram:"shootpress",     description:"4 attackers start in their own half. On signal, sprint forward in a 4v2. Defenders start 5m ahead of goal. Must score within 10 seconds.", coach_notes:"Speed of thought, not just legs. Decide quickly who shoots, who makes the distracting run." , progression:"Reduce the time limit to 8 seconds. Add a third defender to increase realism against a well-organised backline." },
  { id:35, title:"Overlapping Run Drill",        category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"6-10",              home_ready:false, diagram:"shootpress",     description:"Full back overlaps winger on the outside. Winger holds until the overlap is on, then lays off into space. Drill both sides equally.", coach_notes:"Communication is everything — 'on your shoulder' triggers the overlap. Drill the call as much as the movement." , progression:"Reduce rest time to 10 seconds. Add a medicine ball for the plank and glute bridge." },
  { id:36, title:"Shooting Under Pressure",      category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"Any",               home_ready:false, diagram:"shootpress",  description:"Player receives 20m from goal with a defender closing from 10m. Must decide to shoot, turn, or lay off within 2 seconds.", coach_notes:"Make the time pressure real — loud 3-second countdown. Reward the right decision, not just the goals." , progression:"Reduce the decision window to 1 second. Vary the defender's angle of approach so the player must adapt each rep." },
  { id:37, title:"Combination Play into Box",    category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-10",              home_ready:false, diagram:"combo",       description:"3 players combine using one-twos and layoffs to work ball into penalty area and finish. Passive defender becomes active on entry to box.", coach_notes:"Reward fluency. Walk through the pattern at zero speed if players lose shape." , progression:"Reduce the sprint distance to the halfway line only — more sprints, less recovery." },
  { id:38, title:"First Touch & Finish",         category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent",home_ready:true, diagram:"shootpress", description:"A parent serves the ball at varying heights and pace. Player controls with one touch then shoots in two touches max. Solo version: kick against a wall at an angle and react to the rebound.", coach_notes:"First touch direction is the skill — coach where the touch goes, not just that it's controlled." , progression:"Add resistance bands for leg swings and lunges. Increase reps on each movement." },
  { id:39, title:"Wide Attack Patterns",         category:"Attacking", age_groups:["U13","U14","U15"], duration:"10 min", players:"8-12",              home_ready:false, diagram:"wideattack",  description:"Pull-back, early cross, cut inside — attackers run rehearsed patterns from wide areas. Passive defender becomes active once pattern is learned.", coach_notes:"Walk through at zero speed first. Only add defenders once the shapes are familiar." , progression:"Increase speed challenge — set a target number of taps per 30 seconds to beat." },
  { id:40, title:"Set Piece Attack",             category:"Attacking", age_groups:["U13","U14","U15"], duration:"10 min", players:"Full squad",        home_ready:false, diagram:"setpiece",    description:"Practise 2 corner and 1 free kick routine. Near post flick, far post run, short corner. Every player has an assigned role.", coach_notes:"Every player should know exactly where to stand and where to run — no guessing. Repetition is key." , progression:"Add a ball — juggle while walking forward. Set a personal best target to beat each session." },
  { id:41, title:"1v1 Dribble & Finish",         category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs",             home_ready:false, diagram:"shootpress",     description:"Attacker starts with the ball and must beat a defender in a 10x15m channel before shooting. 60-second bouts. Celebrate clever feints even if they don't beat the player.", coach_notes:"Encourage variety of moves — not just pace. Show players 2-3 moves they can practise (stepover, cut inside, drag back)." , progression:"Introduce a passive defender who adds light pressure. Add a second ball." },
  { id:42, title:"Third Man Run",                category:"Attacking", age_groups:["U13","U14","U15"], duration:"10 min", players:"9-12",              home_ready:false, diagram:"combo",       description:"Player A passes to Player B. Player B lays off to Player C who has made a timed run in behind. Focus is entirely on the timing of the third man's movement.", coach_notes:"The third man runs when the ball goes to Player B — not before, not after. This takes repetition. Use cones to mark the run angle." , progression:"Introduce a time limit to switch from 9v9 to 7v7 during the same session." },
  { id:43, title:"2v1 Overload Attack",          category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"9-12",              home_ready:false, diagram:"triangle",         description:"2 attackers vs 1 defender to goal. Attackers must use the overload — pass to create the shooting chance. Defender scores a point for every clearance.", coach_notes:"The player without the ball must move to create the passing angle. If they stand still, the defender can cover both." , progression:"Introduce a pressed defender who adds light pressure to the shape." },
  { id:44, title:"Dribble Through Gates",        category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Any",               home_ready:false, diagram:"gates",       description:"Set 8 gates (pairs of cones) randomly in a 20x20m area. Players dribble through as many gates as possible in 60 seconds. Record score and beat it.", coach_notes:"Head up while dribbling — players must scan for the next gate before they get to it. This is the key coaching point." , progression:"Add moving players — walk through offside scenarios at jogging pace with active defenders." },
  { id:45, title:"Attacking Shape — 9v9",        category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Full squad",        home_ready:false, diagram:"triangle",   description:"Full squad practise shape in possession for 9v9 — wide players pushed high, two central midfielders supporting the striker. Coach feeds ball in and freezes to correct positions.", coach_notes:"Two key questions: are the wide players wide enough? Are the midfielders at the right depth? Freeze and correct before players move." , progression:"Add a second pressing unit. Introduce a time limit — press must win ball within 6 seconds." },

  // ── STRENGTH & CONDITIONING (10) ──────────────────────────────────────────
  { id:46, title:"Cone Dribbling",               category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"weave",       description:"Set up cones in a straight line — bottles or jumpers work just as well. Dribble through focusing on close control using both feet. Start slow, then build speed. Try 5 runs.", coach_notes:"Encourage inside and outside of each foot — not just one. Parents can time runs and challenge their child to beat their time." , progression:"Reduce cone spacing to increase difficulty. Add a ball skill at each cone (stepover, drag-back). Use weaker foot only for a full run." },
  { id:47, title:"Figure Eight Dribbling",       category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"weave",      description:"Place two cones about 5 yards apart. Dribble in a figure-eight pattern to focus on changing direction quickly and using both feet. 10 eights, rest 30 seconds, repeat 3 times.", coach_notes:"Only needs 2 cones or bottles. The figure eight naturally forces both feet if done correctly." , progression:"Introduce in-game analysis — pause and ask players to identify shape breakdowns themselves." },
  { id:48, title:"Core Circuit",                 category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"core",        description:"No equipment needed. 40 seconds on, 20 seconds rest: Plank, Side plank left, Side plank right, Glute bridge, Dead bug. Rest 1 minute, repeat 3 rounds.", coach_notes:"Technique over duration. A 20-second perfect plank beats a 60-second sagging one." , progression:"Move to 11v11 friendly fixtures from March as per FAW guidance." },
  { id:49, title:"Dynamic Warm-Up Routine",      category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"warmup",      description:"Jog on the spot 1 min, then: high knees (30s), heel kicks (30s), leg swings (10 each leg), hip circles (10 each direction), reverse lunge with twist (5 each side). All dynamic — no holding stretches.", coach_notes:"Run this before every home session. The routine becomes a mental warm-up cue over time." , progression:"Run the session with the U13 squad to expose U12 players to faster pace." },
  { id:50, title:"Toe Taps",                     category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"toetaps", description:"Stand over the ball and tap lightly with alternating feet. Start slow, build speed. 30 seconds on, 15 seconds rest for 5 rounds. Count taps and try to beat your score.", coach_notes:"Watch for players leaning back. They should be balanced slightly forward over the ball." , progression:"Increase speed while keeping the ball under control. Try tapping on top of a small step or curb for an extra challenge." },
  { id:51, title:"Ball Juggling",                category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent",home_ready:true,  diagram:"ballmastery",     description:"Juggle using feet, thighs, and head without letting the ball touch the ground. Start with feet only. Record personal best and beat it each session.", coach_notes:"Encourage players to log their PB — the improvement over a season is remarkable and very motivating." , progression:"Introduce thighs and head once feet are consistent. Try alternating feet every touch rather than using the same foot twice." },
  { id:52, title:"Reaction Ball Sprints",        category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Any",                home_ready:false, diagram:"reactionsprint",    description:"Coach holds a cone above their head. On the drop, player sprints forward 10m from a standing start. Vary the direction to work on first-step reactions.", coach_notes:"Focus on the first 3 steps — this is where football acceleration is won or lost." , progression:"Add a ball — dribble in a figure eight pattern. Increase to 15 eights per set." },
  { id:53, title:"Plyometric Box Jumps",         category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"10 min", players:"Any",                home_ready:true,  diagram:"boxstep",        description:"Using a low, stable step or kerb (max 30cm), step up with both feet, then step back down. Reset and repeat. 3 sets of 8 reps, 60s rest between sets.", coach_notes:"Only at U13+. Land softly — absorb the impact through the knees, not the floor." , progression:"Progress to a small hop up instead of a step once the movement feels controlled. Add a 5m sprint immediately after each set." },
  { id:54, title:"Speed Gate Runs",              category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Any",                home_ready:false, diagram:"speedgates",  description:"4 speed gates in a T-shape. Players complete timed runs through different gate combinations. Record times and beat them.", coach_notes:"Players push hardest when they have a time to beat. Pair similar-paced players." , progression:"Add a ball — receive a pass, control, then complete the warm-up movement before returning it." },
  { id:55, title:"Interval Shuttle Run",         category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Any",                home_ready:false, diagram:"shuttle",     description:"Cones at 5m, 10m, 15m. Sprint to 5m back, 10m back, 15m back — that's one rep. 6 reps, 60s rest between each.", coach_notes:"Monitor effort at U12, not time. By U14 introduce a target time to beat." , progression:"Increase to 45 seconds on, 15 seconds rest. Add a stability challenge — single leg tap." },

  // ── AGE GROUP CHANGES — FAW 2025-26 ──────────────────────────────────────
  { id:56, title:"U11 to U12: Moving to 9v9",        category:"Age Group Changes", age_groups:["U12"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",       description:"The step from 7v7 festivals to 9v9 is the biggest change in youth football. Key differences: pitch grows to 64x44 yards, goals 7x16ft, ball size 4, offside rule introduced, a qualified referee controls matches, results count, home and away fixtures replace festivals. Season must start with a non-competitive block before competition begins. Max 18 players per squad. Max 24 competitive weeks per season.", coach_notes:"Walk through offside visually before the season — line players up and show it slowly. Introduce basic positional shape but keep it simple. Season must start non-competitive. Team roster on COMET is compulsory." , progression:"Discuss with players how the pitch feeling bigger will change their positioning and running demands compared to 7v7." },
  { id:57, title:"U12: 9v9 Rules & Regulations",     category:"Age Group Changes", age_groups:["U12"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"default", description:"U12 play 9v9 on a 64x44 yard pitch. 70 minutes (2x35 min halves). Penalty spot 9 yards from goal. Goals 7x16ft. Offside applies. Max 18 players per squad. Goal difference CANNOT be used in league standings. Mercy rule is mandatory — if a team leads by 8 goals, the match is declared over. Goalkeeper cannot pick up a back pass from a teammate. Retreat line — opposition 10 yards from goalkeeper.", coach_notes:"Key FAW rules: no goal difference in standings, mercy rule at 8-goal lead, 50% playing time for all squad members, COMET team roster compulsory. GK cannot handle back passes." , progression:"Print or laminate a simple rules summary for parents and new coaches to reference on match day." },
  { id:58, title:"U12: Offside Rule Explained",       category:"Age Group Changes", age_groups:["U12"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"offside",   description:"Offside is introduced at U12 for the first time. A player is offside if they are in the opposition half, nearer to the goal than both the ball AND the second-last defender, and involved in active play when the ball is played. Key points: you cannot be offside from a goal kick, throw-in, or corner. Being level with the last defender is NOT offside.", coach_notes:"Make it visual, not verbal — line players up and walk through scenarios slowly. Common mistake: players thinking being in the opposition half alone is offside. Repeat until it clicks." , progression:"Add a ball — dribble to each gate and pass through rather than just running." },
  { id:59, title:"U12: Heading Guidelines",           category:"Age Group Changes", age_groups:["U12"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",    description:"FAW 2025-26: Heading is a LOW PRIORITY at U12. When introducing heading technique, the FAW advise: maximum 10 minutes per session, maximum 4 headers per bout, self-serve over short distances only, always use age-appropriate ball at correct pressure. Heading practice must not form any significant part of training. Coaches should encourage a style of play that limits long balls in the air.", coach_notes:"This is FAW guidance for U12 — keep heading minimal and always self-serve. Concussion protocol: any suspected head injury = immediate removal, cannot return to play, parent/guardian advised to seek medical advice. Return only after day 21 if symptom-free for 14 days." , progression:"Revisit this guidance each new season -- FAW advice on heading is updated periodically, so check for the latest recommendations." },
  { id:60, title:"U12: Positive Match Day Culture",   category:"Age Group Changes", age_groups:["U12"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",description:"FAW mandatory match day rules: (1) All squad members must play minimum 50% of total available playing time. (2) Rolling substitutes — players can re-enter after being substituted. (3) Buffer zone of 2 metres from both touchlines is required. (4) Smoking and vaping is banned from the sideline. (5) Spectators must applaud both teams — no shouting instructions. (6) Coaches must not continually shout instructions during matches.", coach_notes:"Plan substitutions in advance. The 2m buffer zone and smoking ban are enforceable FAW rules. No squad player should sit on the bench for the full match — 50% playing time is mandatory, not a target." , progression:"Share this culture guidance with parents at the start of the season so expectations are clear from day one." },
  { id:61, title:"U12 to U13: Pitch Gets Larger",     category:"Age Group Changes", age_groups:["U12","U13"],       duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",       description:"When moving from U12 to U13, the pitch length increases from 64 yards to 76 yards (width 44-54 yards). This is significant — it demands better fitness and faster switching of play. All other U12 rules remain the same. Single age band U13 leagues can operate a fully competitive season. From 1st March, non-competitive 11v11 friendly fixtures can be offered to prepare players for U14.", coach_notes:"Work on fitness and width during U12 to prepare for the larger U13 pitch. From March at U13, organise 11v11 friendlies so players experience the full-size game before moving up." , progression:"Introduce a passive defender to add light pressure to the 7v7 shape." },
  { id:62, title:"U13: Full Competition Rules",        category:"Age Group Changes", age_groups:["U13"],             duration:"10 min", players:"Full squad", home_ready:false, diagram:"positions", description:"U13 is 9v9 on a 76x44-54 yard pitch. 70 minutes (2x35 min halves). Fully competitive for single age band leagues. Goal difference still not permitted in league standings. Mercy rule (8-goal margin) still mandatory. From 1st March, non-competitive 11v11 friendlies can be organised to bridge the gap to U14.", coach_notes:"No goal difference in standings. Mercy rule at 8 goals still applies. Use 11v11 friendlies from March to introduce full positional shape, set pieces, and the larger pitch." , progression:"Run a combined U12/U13 session to expose younger players to the larger 9v9 pitch." },
  { id:63, title:"U13 to U14: Moving to 11v11",        category:"Age Group Changes", age_groups:["U13","U14"],       duration:"10 min", players:"Full squad", home_ready:false, diagram:"positions", description:"U14 is the first age group to play full 11v11 football. Key changes: full-size pitch, size 5 ball, 70-minute matches (2x35 min halves), full IFAB Laws of the Game apply. Players aged 13 on 31st August are eligible. Match day squad 16-18 players (set by Area Association). Fully competitive season. Heading guidelines continue — limit aerial play where possible.", coach_notes:"Prepare players for this during U13 — use the 11v11 friendlies from March. Introduce full positional shape, pressing, and set pieces before the season starts. FAW: 50% playing time still mandatory." , progression:"Add a full offside trap — back 4 step up simultaneously on a verbal trigger." },
  { id:64, title:"U14 to U15: Match Duration Increases",category:"Age Group Changes", age_groups:["U14","U15"],     duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",  description:"U15 increases match duration to 80 minutes (2x40 min halves) — up from 70 minutes at U14. Still 11v11, size 5 ball. Players aged 15 on 31st August are eligible for U15 and U16. Mercy rule (8-goal margin) still applies. Rolling substitutes continue. 50% playing time rule still applies.", coach_notes:"The extra 10 minutes increases physical demands. Build stamina work into training from U14. Tactical awareness and set piece organisation become increasingly important at U15." , progression:"Review fitness and conditioning plans annually as physical demands increase through the age groups." },
  { id:65, title:"FAW Coach Qualifications & DBS",     category:"Age Group Changes", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Full squad", home_ready:false, diagram:"default",description:"FAW requirements for all coaches: (1) Minimum FAW Football Leaders Award required. (2) Valid FAW-approved Enhanced DBS Check for Regulated Activity — mandatory for all coaches. (3) FAW First Aid Award required. Coach to player ratios: U9-U12: 1 qualified coach per 16 players, 1 DBS adult per 8 players. U13-U17: 1 qualified coach per 18 players, 1 DBS adult per 10 players. Minimum 2 supervisors always recommended.", coach_notes:"Ensure all coaches have current DBS checks — these must be FAW-approved Enhanced checks for Regulated Activity. First aid qualification required at every training session and match. Review annually." , progression:"Keep a checklist of coach qualifications and DBS renewal dates, reviewed at the start of each season." },
  // ── GOALKEEPING (10) ──────────────────────────────────────────────────────
  { id:66, title:"GK Handling & Distribution",   category:"Goalkeeping", age_groups:["U12","U13","U14"], duration:"10 min", players:"1 GK + server", home_ready:false, diagram:"gkhandling", description:"GK receives serves at different heights -- rolled, waist height, high. Catches cleanly then distributes by roll, throw or kick. 5 reps of each type.", coach_notes:"Emphasise getting behind the ball. Hands together, elbows in. Distribute quickly after the catch -- don't hold the ball.", progression:"Add a second server from a different angle. GK must decide which type of distribution is appropriate after each save." },
  { id:67, title:"GK Footwork & Positioning",    category:"Goalkeeping", age_groups:["U12","U13"],       duration:"10 min", players:"1 GK",          home_ready:true,  diagram:"gkfootwork", description:"Set up 3 cones across the goal line. GK side-steps between them maintaining a low ready stance, staying on their toes throughout. 4 sets of 30 seconds.", coach_notes:"Feet shoulder-width apart, slight forward lean, weight on toes. No crossing of feet -- side-step only.", progression:"Add a ball serve on coach's signal mid-movement -- GK must react and catch without resetting." },
  { id:68, title:"GK Angle Play",                category:"Goalkeeping", age_groups:["U12","U13","U14"], duration:"10 min", players:"1 GK + 3 shooters", home_ready:false, diagram:"shootpress", description:"Shooters take turns shooting from 3 different positions (centre, left, right of the area). GK must move off the line to cut the angle before each shot.", coach_notes:"GK should move forward and across to the near post side. 'Shrink the target' is the key phrase.", progression:"Add a dribble before the shot so GK must react to movement, not just a static ball." },
  { id:69, title:"GK Crosses & Claiming",        category:"Goalkeeping", age_groups:["U13","U14"],       duration:"10 min", players:"1 GK + crosser", home_ready:false, diagram:"cross", description:"Wide player delivers crosses from the left and right. GK must decide to come and claim or stay on the line. Call 'keeper' loudly when coming. 8 crosses each side.", coach_notes:"Decision-making is the skill -- not every cross should be claimed. Call early and be decisive. One missed call = stay.", progression:"Add a passive attacker in the box to challenge the GK on the cross." },
  { id:70, title:"GK Reaction Saves",            category:"Goalkeeping", age_groups:["U12","U13","U14"], duration:"10 min", players:"1 GK + shooter", home_ready:false, diagram:"shootpress", description:"GK starts on their knees at the centre of the goal. Server shoots low to either side from 8m. GK must scramble and react. 10 reps each side.", coach_notes:"This builds recovery speed and reactions. Praise effort over technique here -- it's meant to be hard.", progression:"Serve from 6m to reduce reaction time. Add a second serve immediately after the first to test recovery." },
  { id:71, title:"GK 1v1 Narrowing",             category:"Goalkeeping", age_groups:["U12","U13"],       duration:"10 min", players:"1 GK + attacker", home_ready:false, diagram:"shootpress", description:"Attacker starts 20m from goal and drives towards goal in a 1v1. GK must advance to narrow the angle and decide when to commit. Rotate attackers every 3 reps.", coach_notes:"GK should come to the edge of the penalty area and set early. Spread the body when the attacker gets close. Don't dive early.", progression:"Give attacker a wider starting position so GK must adjust their angle of approach before setting." },
  { id:72, title:"GK Distribution Accuracy",     category:"Goalkeeping", age_groups:["U12","U13","U14"], duration:"10 min", players:"1 GK + targets",  home_ready:true,  diagram:"wall", description:"Set 3 targets at different distances (5m, 10m, 20m). GK practises rolling to 5m, throwing overarm to 10m, and kicking to 20m. 5 reps each.", coach_notes:"Accuracy before distance. A bad goal kick that lands with the opposition is worse than a short accurate one.", progression:"Add a receive-and-return element -- the target passes back for GK to catch and redistribute immediately." },
  { id:73, title:"GK Low Dive Technique",        category:"Goalkeeping", age_groups:["U12","U13"],       duration:"10 min", players:"1 GK + server",  home_ready:false, diagram:"gkhandling", description:"Server rolls ball firmly to either side of the GK from 8m. GK dives low, collects in two hands, and recovers to feet before next serve. Rest 10s between dives.", coach_notes:"Lead with the bottom hand, top hand on top of the ball. Get body behind the ball -- don't just reach out.", progression:"Serve alternating sides so GK cannot anticipate direction. Increase pace gradually." },
  { id:74, title:"GK Set Piece Positioning",     category:"Goalkeeping", age_groups:["U13","U14"],       duration:"10 min", players:"Full squad",      home_ready:false, diagram:"setpiece", description:"Walk through GK positioning for corners (near post, 2-3 steps off line), free kicks at different angles, and penalty positioning. Static first, then with movement.", coach_notes:"GK should own their area verbally -- organising defenders is part of the role. Encourage shouting names early.", progression:"Run live set pieces with GK organising defenders using real instructions." },
  { id:75, title:"GK Penalty Technique",         category:"Goalkeeping", age_groups:["U13","U14"],       duration:"10 min", players:"1 GK + penalty taker", home_ready:false, diagram:"shootpress", description:"5 penalty takers each take 3 penalties. GK focuses on staying central, staying tall, and moving at the last possible moment. Log save success.", coach_notes:"Don't over-coach the dive direction -- teach patience. The best GKs at this age stay big and wait for the kick.", progression:"Have penalty takers shoot to a called side to practice moving quickly to a pre-decided corner." },

  // ── FROM GRASSROOTS FOOTBALL UK VOL.1 ─────────────────────────────────────

  // S&C / Pre-Season (76-78)
  { id:76, title:"Dirty Dozen / Sickly Six",        category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"20 min", players:"Full squad", home_ready:false, diagram:"shuttle", description:"Split squad into groups by fitness level. Each player completes 12 full-pitch sprints (or 6 for Sickly Six). After each sprint, 10 reps of a different exercise -- star jumps, sit-ups, press-ups, squats, lunges, burpees, tuck jumps etc. Record times each week and stagger starts in Week 2 based on Week 1 gaps.", coach_notes:"Equalises competition -- slower players get head starts in later weeks so everyone is racing against each other. Great for building team culture.", progression:"Reduce recovery between exercises. Add a ball -- dribble the pitch length instead of sprinting." },
  { id:77, title:"S.M.L -- Short Medium Long Sprints", category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"15 min", players:"Full squad", home_ready:false, diagram:"shuttle", description:"Set 3 markers: S = quarter pitch, M = halfway, L = full length. Write S, M, L on paper slips and put in a bag. Each player picks a slip to build the session's sprint sequence. Kids love the tension of the draw. Run 3-5 sets.", coach_notes:"The element of chance makes it fun and removes any sense of the coach making it deliberately hard. Players buy in immediately.", progression:"Add a ball -- the sprint becomes a dribble. Players must arrive at the cone under control." },
  { id:78, title:"Escape Room Ball Mastery",          category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"6-12",         home_ready:true,  diagram:"rondo", description:"Set up a circle with cones. One player starts inside with a ball and must dribble out past the circle boundary. Players on the outside try to kick the ball back in whenever it gets close. If the player escapes, they swap with whoever kicked it last.", coach_notes:"Brilliant warm-up game -- high energy, lots of touches, natural pressing practice without calling it that.", progression:"Add a second ball and second player inside. Reduce circle size." },

  // Passing (79-85)
  { id:79, title:"Zig Zag Passing Race",              category:"Passing",                  age_groups:["U12","U13","U14"], duration:"10 min", players:"8-16",         home_ready:false, diagram:"gates", description:"Set flat discs 10-15 yards apart in a zig-zag line with a player on each. Ball starts at one end. Players pass to the next in the zig-zag, following their pass to the next cone. Time how long it takes to reach the end and back. Challenge the group to beat their time each week.", coach_notes:"Urgency and accuracy are both tested. Players learn to lead the target, pass into space, and move quickly after passing.", progression:"One touch only. Add a second ball starting from the opposite end simultaneously." },
  { id:80, title:"Beat the Clock Rondo",              category:"Passing",                  age_groups:["U12","U13"],       duration:"10 min", players:"8-14",         home_ready:false, diagram:"rondo", description:"Players form a circle around the coach. The coach times how many passes the group can complete in 60 seconds without losing possession to the coach in the middle. Record the score each week and challenge them to beat it.", coach_notes:"The competitive element drives intensity. Start without a defender then progress. Great for quick decision-making under light pressure.", progression:"Add a second defender. Reduce circle size. Limit to two touches, then one touch." },
  { id:81, title:"Double Rondo Head to Head",         category:"Passing",                  age_groups:["U13","U14"],       duration:"15 min", players:"12-16",        home_ready:false, diagram:"rondo", description:"Two equal groups each form a rondo circle. Players are numbered. When a defender wins the ball in one rondo, they call a number. That numbered player must immediately break into the opposite rondo to defend. The original defender joins that rondo as an outfield player.", coach_notes:"Creates chaos in a positive way -- players must stay alert even when not in possession. Excellent for scanning and awareness.", progression:"Shorten the distance between the two circles. Add a time limit -- defender must win ball within 8 seconds." },
  { id:82, title:"Split the Defence Passing",         category:"Passing",                  age_groups:["U12","U13","U14"], duration:"10 min", players:"8-12",         home_ready:false, diagram:"lanes", description:"Divide pitch into 3 zones with 2 defenders positioned between zones. Attackers must pass through each zone to reach the end. If a defender intercepts, teams swap. Encourages finding gaps, weight of pass, and movement off the ball.", coach_notes:"Reinforce that splitting the defence is about timing and disguise -- look one way, pass another. Celebrate the 'through ball'.", progression:"Add a second defender per zone. Reduce zone width to create tighter passing angles." },
  { id:83, title:"Heads Up Pass and Move",            category:"Passing",                  age_groups:["U12","U13"],       duration:"10 min", players:"8-14",         home_ready:false, diagram:"triangle", description:"Players pass and follow in a square or triangle but must call the name of the person they are passing to before they pass. The receiver must acknowledge with eye contact before the ball is played. If no call is made, the pass doesn't count.", coach_notes:"Goes against instinct -- players want to watch the ball. This forces scanning before passing. Massive long-term benefit.", progression:"Add a defender. Require the passer to move to a different position -- not just follow the pass." },
  { id:84, title:"Passing and Control Reactions",     category:"Passing",                  age_groups:["U12","U13","U14"], duration:"10 min", players:"Pairs + coach", home_ready:true,  diagram:"wall", description:"In pairs, Player A passes to Player B who must control and immediately pass to a third target (cone, coach, or another player) called out by the coach at the moment of receiving. Player B must scan before the ball arrives to react quickly enough.", coach_notes:"Simulates real match conditions -- players rarely know where they will pass before they receive. Builds quick decision-making.", progression:"Increase the number of targets to 4. Reduce reaction time by calling the target later." },
  { id:85, title:"Long Pass Switch Play",             category:"Passing",                  age_groups:["U13","U14"],       duration:"10 min", players:"8-12",         home_ready:false, diagram:"switch", description:"Set up in a wide formation. Players must complete 3 short passes before switching the ball with a long diagonal pass to the opposite flank. The receiving player controls and the sequence repeats. Emphasise disguise on the switch ball.", coach_notes:"Long passing is not a hoof -- it is a measured, disguised switch. The preparation and body position before the pass are as important as the pass itself.", progression:"Add a passive defender who can intercept the switch ball. Increase distances gradually." },

  // Attacking (86-87)
  { id:86, title:"Crossing at Pace",                  category:"Attacking",                age_groups:["U13","U14"],       duration:"10 min", players:"6-10",         home_ready:false, diagram:"cross", description:"Wide player starts at halfway, drives at pace toward the byline and crosses into the box. Two strikers make near-post and far-post runs. Cross must be delivered before reaching the goal line. Rotate positions every 4 crosses. Focus on quality of delivery at speed.", coach_notes:"The crossing zone is the area of maximum opportunity -- the closer to the byline, the more the goalkeeper is taken out of the picture. Reinforce this.", progression:"Add a passive defender following the crosser. Vary delivery -- driven low, pulled back, floated far post." },
  { id:87, title:"Short Corner Routines",             category:"Attacking",                age_groups:["U12","U13","U14"], duration:"10 min", players:"5-8",          home_ready:false, diagram:"setpiece", description:"Practice 3 short corner routines using hand signals: Routine 1 -- two-player short with shot from edge of box. Routine 2 -- decoy runner to far post, ball played to unmarked midfielder. Routine 3 -- corner taker receives ball back, drives to create shooting angle. Use a signal system so players recognise which routine is on.", coach_notes:"Short corners work best when they are rehearsed and automatic. Signals must be clear and given early. FAW 9v9 makes corners very impactful -- worth the time.", progression:"Add passive defenders to each routine. Run all 3 routines consecutively without stopping." },


  // ── ADDITIONAL DRILLS ──────────────────────────────────────────────────────

  // Passing (88-89)
  { id:88, title:"Wall Rebound Combinations",     category:"Passing",                  age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"wall", description:"Pass against a wall, control the rebound, then pass again -- alternate feet each time. Progress to one-touch return without stopping the ball. Try 20 reps each foot.", coach_notes:"Focus on the first touch setting up the next pass -- not just stopping the ball dead. Encourage a soft, cushioned touch.", progression:"Move closer to the wall to reduce reaction time. Add a target zone on the wall to hit. One-touch only -- no controlling touch allowed." },
  { id:89, title:"Numbered Cone Call",            category:"Passing",                  age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"targetpass", description:"Set up 4 cones numbered 1-4 around the garden. Parent calls a number and the player must pass accurately to that cone as quickly as possible. Reset and repeat with random numbers.", coach_notes:"This combines reaction speed with passing accuracy under time pressure -- exactly what happens in a match when a passing option appears suddenly.", progression:"Reduce the time allowed to react. Call two numbers in sequence -- player must pass to both correctly. Increase distance to cones." },

  // Dribbling / Ball Mastery (90-92)
  { id:90, title:"Sole Rolls & Drags",             category:"Strength & Conditioning",  age_groups:["U12","U13"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"ballmastery", description:"Using only the sole of the foot, roll the ball side to side, then practice drag-backs (pulling the ball back with the sole). Great for tight spaces -- can be done in a small room. 3 sets of 30 seconds each movement.", coach_notes:"Foundational ball mastery -- this builds the close control needed for turning away from pressure in games. Little and often works best.", progression:"Increase speed while maintaining control. Add a 180-degree turn using the drag-back mid-movement." },
  { id:91, title:"Cruyff Turn Practice",           category:"Strength & Conditioning",  age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"ballmastery", description:"Practice the Cruyff turn against a wall or cone -- knock the ball one way with the outside of the foot, then use the inside of the standing foot to drag it behind and change direction. Repeat 15 times each side.", coach_notes:"A genuine matchday skill move, not just for show -- excellent for losing a marker in tight areas. Encourage a natural, low body position.", progression:"Add a cone to represent a defender and time the turn to beat it. Increase speed of approach before the turn." },
  { id:92, title:"1v1 vs Shadow Defender",         category:"Strength & Conditioning",  age_groups:["U12","U13"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"tackle", description:"Place a cone to represent an imaginary defender. Approach at pace and use a body feint or skill move to 'beat' the defender, then accelerate away. Repeat from different angles.", coach_notes:"Body feints and change of pace are more effective than complicated skill moves at this age -- keep it simple and realistic to matches.", progression:"Add a second cone to beat in sequence. Time each rep and try to beat your own record." },

  // Shooting (93-94)
  { id:93, title:"Both-Feet Finishing",            category:"Attacking",                age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"shootpress", description:"Parent rolls balls alternately to the player's left and right foot from close range. Player must finish first-time into a goal or target using whichever foot receives the ball. 15 reps each foot.", coach_notes:"Confidence on the weaker foot is one of the biggest gaps at this age -- this drill forces genuine practice rather than avoidance.", progression:"Increase the pace and distance of the roll. Add a defender jogging back to close down the shot." },
  { id:94, title:"Target Zone Shooting",           category:"Attacking",                age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"shootpress", description:"Divide a goal or wall into zones using chalk, tape or cones -- corners worth 3 points, middle worth 1. Player takes 10 shots and totals their score. Try to beat the score each week.", coach_notes:"Gamifying shooting practice keeps it engaging over repeated home sessions. Emphasise placement over power throughout.", progression:"Reduce the size of the high-value zones. Add a one-touch finish requirement -- no controlling touch before shooting." },

  // Fitness (95-96)
  { id:95, title:"Stair Sprints",                  category:"Strength & Conditioning",  age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"stairs", description:"If stairs are available, sprint up at pace, walk down to recover. Repeat 8-10 times. Builds explosive leg power and short sprint speed relevant to quick match bursts.", coach_notes:"Only suitable where a safe staircase is available -- never on wet or uneven steps. Full recovery walk down is essential.", progression:"Increase reps to 12-15. Add two stairs at a time on the way up once technique is solid." },
  { id:96, title:"Wall Sit Challenge",             category:"Strength & Conditioning",  age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"core", description:"Sit against a wall with knees at 90 degrees as if sitting in an invisible chair. Hold for as long as possible. Record the time and try to beat it each week. 3 attempts with 1 minute rest between.", coach_notes:"Simple isometric strength work for the legs -- no equipment needed and easy to track progress over the season.", progression:"Add a ball held out in front with arms extended to increase difficulty. Try single-leg wall sits once double-leg is comfortable." },

  // Training-only tactical (97-98)
  { id:97, title:"Rondo with Conditions",          category:"Passing",                  age_groups:["U13","U14"],       duration:"10 min", players:"8-14",                  home_ready:false, diagram:"rondo", description:"Standard rondo but with a condition changed each round -- e.g. weaker foot only, one touch only for outside players, or must play to the player diagonally opposite. Rotate conditions every 2 minutes.", coach_notes:"Conditions force players out of comfortable habits and highlight technical gaps -- rotate through several conditions in one session.", progression:"Combine two conditions at once, e.g. weaker foot AND one touch. Add a second defender." },
  { id:98, title:"Overload to Underload Transition",category:"Attacking",               age_groups:["U13","U14"],       duration:"15 min", players:"10-12",                 home_ready:false, diagram:"counter", description:"Start 4v2 in a grid. On a turnover, the 2 defenders become attackers in transition against 2 of the original 4 who must recover -- creating a fast 2v2 or 2v3 moment. Reset after each transition.", coach_notes:"Teaches the mentality shift needed the instant possession is lost -- who presses, who recovers, who covers. High tempo, short reps.", progression:"Reduce the grid size to increase transition speed. Add a small goal for the transitioning team to attack." },

  // Goalkeeping (99-100)
  { id:99, title:"1v1 Home Reaction Drill",        category:"Goalkeeping",              age_groups:["U12","U13","U14"], duration:"10 min", players:"1 GK + parent",         home_ready:true,  diagram:"gkhandling", description:"Parent throws or rolls the ball at varying heights and speeds from close range. GK reacts and catches or parries. Mix low, high, and side-to-side serves. 20 reps.", coach_notes:"Great low-impact home session for goalkeepers between training sessions -- keeps reactions sharp without needing a full pitch.", progression:"Reduce the distance between server and GK to shorten reaction time. Add a call-out of left/right just before serving." },
  { id:100, title:"Command & Communication",       category:"Goalkeeping",              age_groups:["U13","U14"],       duration:"10 min", players:"Full squad",            home_ready:false, diagram:"setpiece", description:"Set up a defensive set piece scenario (corner or free kick). GK must organise the defensive line verbally -- calling names, pointing to zones, communicating early and clearly before the ball is delivered.", coach_notes:"Communication is a coachable GK skill just like handling -- many young keepers are quiet by nature and need active encouragement to speak up. Praise loud, clear, early calls specifically.", progression:"Add attacking runners the GK must call out by name as they move. Run consecutive corners without resetting to test sustained communication." },


  // ── STRENGTH, CONDITIONING & PLYOMETRICS ──────────────────────────────────

  { id:101, title:"Vertical Jumps",               category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"vertjump", description:"No equipment needed. From standing, dip into a quarter squat and explode straight up as high as possible, landing softly. 3 sets of 8 reps with full recovery between reps -- this is about power, not speed.", coach_notes:"Land softly through the whole foot, knees slightly bent -- never land stiff-legged. Quality of landing matters more than height of jump. Not suitable for U12 -- growth plates still developing.", progression:"Add a reach upward with both arms at the peak of the jump. Try touching a mark on a wall slightly higher each week." },
  { id:102, title:"Broad Jumps",                  category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"broadjump", description:"No equipment needed. From standing, jump forward as far as possible using both arms and legs, landing softly on both feet. Use a natural marker like a crack in the pavement or a footprint to judge distance. 4 sets of 5 jumps with full recovery.", coach_notes:"This builds horizontal power relevant to acceleration out of tackles and first steps in sprints. Full recovery between jumps is essential -- this is not a conditioning drill, it's a power drill.", progression:"Try for 3 continuous jumps in a row (bounding) rather than single jumps with reset. Compare distance weekly and log a personal best." },
  { id:103, title:"Lateral Bounds",               category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"lateralbound", description:"Jump sideways from one foot to the other, covering as much distance as possible, sticking the landing for 2 seconds before jumping back. 3 sets of 6 each direction.", coach_notes:"Builds the lateral power needed for changing direction quickly -- directly relevant to defending 1v1 situations. Control on landing is the priority, not speed.", progression:"Reduce the stick-landing time to 1 second. Add a small hop in between direction changes rather than a dead stop." },
  { id:104, title:"Tuck Jumps",                   category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"tuckjump", description:"Jump straight up, pulling both knees towards the chest at the peak of the jump, then land softly. 3 sets of 8 reps with full recovery -- this is a demanding exercise, ensure adequate rest.", coach_notes:"High-intensity plyometric -- limit total volume for this age group and always prioritise landing mechanics over height achieved.", progression:"Increase reps gradually to 10 per set only once form stays consistent throughout. Add a 90-degree twist mid-air for advanced players." },
  { id:105, title:"Hip & Glute Activation",       category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"warmup", description:"No equipment needed. Perform lateral lunges, standing hip circles, and glute bridges. 3 sets of 10 lunges each side plus 15 glute bridges.", coach_notes:"Excellent for activating the hip and glute muscles before training -- helps prevent common youth football injuries around the knee and ankle.", progression:"Add a single-leg glute bridge once double-leg is comfortable. Increase lunge depth gradually." },
  { id:106, title:"Single Leg Balance Challenge",  category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"balance", description:"No equipment needed. Stand on one leg for 30 seconds, then switch. Progress to closing your eyes, then to reaching the free leg forward, sideways and behind while balancing. 3 rounds each leg.", coach_notes:"Balance and proprioception directly reduce ankle injury risk -- often overlooked in youth programmes despite being simple and free to do.", progression:"Try balancing on a folded towel or cushion for an unstable surface. Add small hops on the spot while balancing on the standing leg." },
  { id:107, title:"Bodyweight Circuit",           category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"15 min", players:"Solo",                  home_ready:true,  diagram:"circuit", description:"Circuit of squats, lunges, press-ups and sit-ups -- 30 seconds each exercise, 15 seconds rest, repeat the circuit 3 times through. No equipment needed.", coach_notes:"A complete, equipment-free full body session for home. Encourage good form over speed, especially on squats and lunges.", progression:"Add a fourth round. Introduce jump squats and press-up variations (wide, diamond) once base strength is established." },
  { id:108, title:"Agility Footwork Patterns",    category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"ladder", description:"No equipment needed. Imagine a row of squares on the ground (or mark them with chalk if available). Perform in-in-out-out, lateral shuffles, and single-leg hops through each imagined square. 4 patterns, 3 reps each.", coach_notes:"Footwork speed transfers directly to change of direction on the pitch. Precision first, then add speed once patterns are clean.", progression:"Increase speed while maintaining accuracy. Try patterns backward once forward is mastered." },
  { id:109, title:"Hill or Incline Sprints",       category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"15 min", players:"Solo",                  home_ready:true,  diagram:"shuttle", description:"Find a gentle hill or incline. Sprint up at maximum effort, walk back down to recover fully. Repeat 6-8 times. Builds leg power and top-end speed without the joint impact of flat sprinting.", coach_notes:"Naturally reduces stride length and impact forces compared to flat sprinting, making it a safer way to build sprint power at this age.", progression:"Increase to 10 reps. Find a slightly steeper incline once conditioning improves." },
  { id:110, title:"Plank to Press-Up",            category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"plankpress", description:"Starting in a forearm plank, push up one arm at a time into a full press-up position, then lower back down one arm at a time. Alternate the leading arm each rep. 3 sets of 8.", coach_notes:"Builds core and upper body stability together -- helps with physical duels and staying balanced under contact.", progression:"Slow the tempo down to 3 seconds per transition. Add a shoulder tap at the top of each press-up." },
  { id:111, title:"Jump & Stick Landing",          category:"Strength & Conditioning", age_groups:["U14"],             duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"stickland", description:"No equipment needed. Jump straight up a small amount, then land on both feet, absorbing the landing and holding completely still for 2 seconds. Focus entirely on a soft, controlled landing. 3 sets of 6.", coach_notes:"This is a landing-mechanics drill, not a jumping drill -- the jump height is incidental, the controlled landing is everything. U14 only due to the loading involved.", progression:"Progress to a small jump forward immediately after landing once the stick landing is consistently controlled." },
  { id:112, title:"Core Anti-Rotation Hold",       category:"Strength & Conditioning", age_groups:["U13","U14"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"antirotation", description:"No equipment needed. Extend both arms straight out to one side at shoulder height while maintaining a strong, still core -- resist the urge to twist or lean. Hold 20 seconds each side, 3 rounds.", coach_notes:"Builds the rotational core strength needed to hold off physical challenges and strike the ball with power while staying balanced.", progression:"Increase hold time to 30 seconds. Add a gentle push from a parent against the extended arms to challenge stability further." },


  // ── SCANNING & AWARENESS ───────────────────────────────────────────────────
  { id:113, title:"Shoulder Check Passing",        category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"Pairs",             home_ready:true,  diagram:"scanning", description:"In pairs 8m apart, Player A passes to Player B. Before the ball arrives, B must check over their shoulder to spot a cone placed randomly behind them by the coach or parent. B calls out the colour/number of the cone before controlling the ball. 15 reps each.", coach_notes:"This isolates the scan as its own skill rather than bundling it into a full game. Players cannot fake it -- they must genuinely turn their head and see something specific.", progression:"Reduce the passing distance to shorten reaction time. Add two cones and call both out in order." },
  { id:114, title:"Numbered Bibs Awareness Game",  category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"8-12",               home_ready:false, diagram:"rondo", description:"All players wear numbered bibs. In a small possession game, the coach shouts a number every 15-20 seconds. Any player in possession when a number is called must immediately find and pass to that numbered player, wherever they are on the pitch.", coach_notes:"Forces constant scanning of the wider picture, not just the player closest to them. Players who only ever look at the ball will struggle here -- that's the point.", progression:"Call two numbers in sequence for a longer combination. Reduce the time between number calls." },
  { id:115, title:"Traffic Light Scanning",        category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"6-10",               home_ready:false, diagram:"triangle", description:"Coach holds up a red, yellow or green cone before playing a pass. Green means play first time, yellow means take a touch and pass, red means dribble instead of passing. Players must scan the coach's signal without breaking their receiving technique.", coach_notes:"Splits attention between the ball and an external cue -- exactly what happens with teammates' calls and opponents' positions in a real match.", progression:"Increase the speed of the passing sequence. Add a defender to increase realistic pressure." },
  { id:116, title:"Look Up Before You Receive",    category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"scanning", description:"Parent stands 8m away holding up 1, 2 or 3 fingers randomly and passes the ball. The player must call out the number of fingers shown at the moment the ball is received, forcing them to look up rather than down at the ball as it arrives.", coach_notes:"A simple home version of scanning practice -- no equipment beyond a ball and a willing parent. Repetition here builds a habit that transfers directly to matches.", progression:"Increase the passing speed. Add a second parent/coach holding fingers up from a different angle to check both sides." },
  { id:117, title:"Blind Turn Awareness",          category:"Passing", age_groups:["U13","U14"],       duration:"10 min", players:"6-10",               home_ready:false, diagram:"channel", description:"Player receives with their back to goal in a channel. Before turning, they must call out whether it's safe to turn based on a defender's starting position (told by the coach beforehand: 'tight' or 'loose'). Correct decision = turn and drive forward; wrong decision = lay it off instead.", coach_notes:"Builds the decision layer on top of the physical turn -- many players can turn well technically but turn into pressure because they didn't scan first.", progression:"Remove the coach's verbal cue -- player must scan and decide entirely for themselves before receiving." },
  { id:118, title:"Peripheral Vision Grid Passing", category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"8-12",               home_ready:false, diagram:"lanes", description:"Players spread across a large grid with 2-3 balls in play simultaneously. Players must pass to any free teammate while staying aware of the other balls moving around them, avoiding collisions and interceptions.", coach_notes:"Multiple balls forces genuinely wide scanning rather than narrow focus on one game state -- very demanding but excellent for game awareness at busier moments in a match.", progression:"Add a fourth ball. Reduce the grid size to increase the awareness demand." },



  // ── POSITIONAL AWARENESS ───────────────────────────────────────────────────
  { id:119, title:"Know Your Position Grid",       category:"Age Group Changes", age_groups:["U12","U13"],       duration:"10 min", players:"9-14",               home_ready:false, diagram:"positions", description:"Set up the full team shape with cones marking each position. Players walk through their zone and its boundaries, then a coach calls a position -- every player must point to where that player should be standing right now.", coach_notes:"This is about spatial awareness, not memorising a diagram -- players should understand WHY a position sits where it does relative to the ball and teammates, not just recite a formation.", progression:"Add a moving ball -- players must adjust their pointed position as the ball moves across the pitch. Test understanding of covering for a teammate out of position." },
  { id:120, title:"Shape Shuffle -- Ball Side Shifts", category:"Age Group Changes", age_groups:["U12","U13","U14"], duration:"10 min", players:"9-14",               home_ready:false, diagram:"defshape", description:"Full team in defensive shape. Coach or a player passes the ball to different areas of the pitch. The whole team must shift as a unit -- players furthest from the ball tuck in, players nearest engage. No dribbling, just shape movement.", coach_notes:"The classic mistake at this age is players staying flat and square regardless of where the ball is. Reward players who instinctively shift and compress space.", progression:"Add a passive attacking team moving the ball quickly to test how fast the defensive shape can reset." },
  { id:121, title:"Third Man Positioning Run",      category:"Attacking",         age_groups:["U13","U14"],       duration:"10 min", players:"6-10",               home_ready:false, diagram:"combo", description:"Three attackers positioned to form a passing triangle. As Player A passes to Player B, Player C must recognise the pass and move into space to become the next passing option -- always thinking one pass ahead of the ball.", coach_notes:"This teaches players to position themselves based on where the play is going, not where it currently is -- a genuinely advanced concept worth introducing early.", progression:"Add a defender who can intercept if the third man is too slow to react. Increase to a 4-player rotation." },
  { id:122, title:"Home: Position Photo Challenge",  category:"Age Group Changes", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"positions", description:"Using the team formation diagram from the app or a printed pitch, the player explains out loud where their position sits and why -- e.g. \"I'm a CB so I stay central and don't follow the ball wide.\" A parent can ask \"what if...\" scenario questions.", coach_notes:"Understanding positioning conceptually at home reinforces what's drilled on the pitch -- players who can explain their role tend to occupy it more consistently in matches.", progression:"Have the player explain a teammate's position too, building broader tactical understanding of the team as a whole." },
  { id:123, title:"Rotate and Recognise",           category:"Age Group Changes", age_groups:["U13","U14"],       duration:"15 min", players:"9-14",               home_ready:false, diagram:"positions", description:"Small-sided game where every player rotates through 2-3 different positions across the session (e.g. a winger plays as a full-back for 10 minutes). Coach pauses play periodically to ask players what their current position requires of them.", coach_notes:"Playing multiple positions builds far better tactical understanding of the whole team than only ever playing one role -- especially valuable heading into the 11v11 transition.", progression:"Rotate positions more frequently (every 5 minutes) to sharpen quick adaptation." },
  { id:124, title:"Covering the Space Behind",       category:"Tackling",          age_groups:["U13","U14"],       duration:"10 min", players:"6-8",                home_ready:false, diagram:"channel", description:"Two defenders positioned in a channel. When one defender steps out to press the ball, the other must automatically shift across to cover the space they've vacated -- practiced first without pressure, then with an attacker trying to exploit the gap.", coach_notes:"This is the foundation of defensive covering -- a skill that separates organised defences from ones that get exposed by a single well-timed run.", progression:"Add a third defender to create a back three covering pattern. Add a real attacking outlet to punish slow covering." },

  // ── PLAYING UNDER PRESSURE ──────────────────────────────────────────────────
  { id:125, title:"One-Touch Under Pressure",       category:"Passing",           age_groups:["U13","U14"],       duration:"10 min", players:"6-10",               home_ready:false, diagram:"onetouch", description:"Three attackers keep the ball moving with one touch only inside a grid, while a defender closes down aggressively. If the defender wins the ball or a player takes two touches, they swap in as the new defender.", coach_notes:"One-touch play forces players to scan and decide before the ball arrives rather than controlling first and thinking after -- exactly what real match pressure demands.", progression:"Reduce the grid size to increase pressure intensity. Add a second defender for a 3v2." },
  { id:126, title:"Shot Clock Passing",             category:"Passing",           age_groups:["U12","U13"],       duration:"10 min", players:"8-12",               home_ready:false, diagram:"rondo", description:"Standard rondo, but the group has a visible or audible countdown (e.g. 5 seconds) to complete each pass once they receive the ball. Miss the count and possession switches to the defenders.", coach_notes:"Time pressure is a different stress to physical pressure -- both need practising separately. This builds decisiveness and reduces over-dwelling on the ball.", progression:"Reduce the count to 3 seconds. Combine with a defender closing down physically at the same time." },
  { id:127, title:"Composed Under the High Press",  category:"Passing",           age_groups:["U13","U14"],       duration:"15 min", players:"8-12",               home_ready:false, diagram:"press", description:"Build-up play from the goalkeeper or back line against an aggressive high press. Team in possession must find a way through calmly -- switching play, playing round the press, or going long when the pressure is too intense to play short.", coach_notes:"Introduce the idea that playing under pressure isn't just about skill -- it's about making the right decision for the situation, sometimes that decision is a long ball to relieve pressure, and that's not failure.", progression:"Increase the number of pressing players. Add a rule that a mistake under pressure results in an immediate shooting opportunity for the pressing team, raising the stakes realistically." },
  { id:128, title:"Home: Wall Pass Under a Clock",  category:"Passing",           age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"onetouch", description:"Pass against a wall and control the rebound within a set time limit called out by a parent (e.g. \"3 seconds!\") -- if the player takes too long, they lose the rep and must reset. Builds quick, composed touches under simulated pressure.", coach_notes:"Home pressure drills are just as valuable as physical defenders -- a ticking clock creates genuine urgency that mirrors what a closing defender feels like.", progression:"Reduce the time limit gradually. Call out a direction (left/right) the player must pass to under time pressure, combining decision-making with speed." },
  { id:129, title:"Pressure Cooker Small-Sided Game", category:"Attacking",        age_groups:["U13","U14"],       duration:"15 min", players:"8-12",               home_ready:false, diagram:"shootpress", description:"Small-sided game played in a reduced pitch size relative to player numbers, forcing constant pressure and quick decisions. No stopping for coaching during play -- let the pressure do the teaching, debrief after.", coach_notes:"Sometimes the best way to build composure under pressure is simply repeated exposure to it in a game setting rather than isolated drills -- this session is about volume of pressured reps.", progression:"Reduce the pitch size further as the session progresses to increase intensity in the final minutes." },
  { id:130, title:"Recognise and Release",          category:"Passing",           age_groups:["U12","U13","U14"], duration:"10 min", players:"6-10",               home_ready:false, diagram:"scanning", description:"Player receives the ball with a defender closing in from a random angle called by the coach just before the pass arrives. Player must scan, recognise the pressure direction, and release the ball away from it within 2 seconds.", coach_notes:"Combines scanning with pressure recognition -- two skills that are often taught separately but need to work together in a real match moment.", progression:"Reduce the reaction window to 1 second. Add a genuine defender applying real pressure instead of a coach call." },

  // ── NEW ADDITIONS (Sept 2026) ───────────────────────────────────────────────
  { id:131, title:"Six-Cone Rotation Passing",      category:"Passing",   age_groups:["U12","U13"],       duration:"10 min", players:"5",   home_ready:false, diagram:"sixcone",     description:"Six cones arranged in a 15x25m rectangle, five players each starting on a cone with one left empty. As the ball is passed, the passer must sprint into the empty cone before the next pass arrives, keeping the group rotating continuously.", coach_notes:"The habit we want is movement immediately after the pass -- not admiring it. Call out any player who stands still once they've released the ball.", progression:"Limit to one-touch passing only. Add a rule that no player may pass to whoever they last received from, forcing wider scanning." },
  { id:132, title:"Four Corners Duel",              category:"Tackling",  age_groups:["U12","U13","U14"], duration:"10 min", players:"8+",  home_ready:false, diagram:"fourcorners", description:"Split the squad into four small teams, one at each corner of a 20x20m grid. The coach rolls or throws a ball into the middle and calls 'go' -- the first player from each corner races to win it and must hold possession under pressure from the other three for 5 seconds before returning it to the coach.", coach_notes:"This is about winning first contact -- reward players who go in with real intent and a low centre of gravity, not just whoever is quickest.", progression:"Vary the type of ball served (bouncing, spinning, driven) so players must adjust to the flight before competing for it. First team to 5 points wins." },
  { id:133, title:"3-Man Box Warm-up",              category:"Passing",   age_groups:["U12","U13","U14"], duration:"10 min", players:"3 (trios)", home_ready:false, diagram:"boxwarmup", description:"A 4x4m box marked by four cones. One player works inside the box while two passers stand 7-10 yards away on adjacent sides. The worker receives, opens their body, and plays to the second passer, then sprints around one of the box cones before receiving again from the other direction. Rotate the worker every 30-60 seconds.", coach_notes:"Watch the first touch direction -- it should set up the next pass, not just get the ball under control. A good one to run before every session while players are still fresh.", progression:"Restrict the worker to one touch. Add a second worker inside the box to increase the decision-making." },
  { id:134, title:"Jam-Packed Dribbling",           category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"5+",  home_ready:false, diagram:"jampacked",   description:"Mark a 20-yard circle. Every player has a ball and dribbles around the outside of the circle in the same direction. On the coach's call -- jog, full speed, cut back, or cross through the middle -- players react instantly, with 'cross' sending everyone through the crowded centre at once while keeping the ball close.", coach_notes:"Heads up is everything here -- with balls and bodies everywhere, players must scan constantly. Encourage close control and using both feet, not just the strong side.", progression:"Add your own extra commands. Reduce the size of the circle to increase the congestion and difficulty." },
  { id:135, title:"Passing Name Game",              category:"Passing",   age_groups:["U12","U13"],       duration:"10 min", players:"6+",  home_ready:false, diagram:"namegame",    description:"Players form a circle. Before receiving a pass, each player must call out the name of the teammate they intend to pass to next -- forcing them to decide and scan a full pass ahead of the ball arriving. Two touches only: one to receive, one to pass, and never straight back to whoever just passed to you.", coach_notes:"This is a thinking drill as much as a passing one. Some players will freeze because they haven't decided who's next -- that hesitation is exactly what we're training out.", progression:"Add a second ball to increase the mental load. Let players move freely within the circle rather than staying fixed." },
  { id:136, title:"Soccer Tennis",                  category:"Attacking", age_groups:["U13","U14","U15"], duration:"15 min", players:"4+",  home_ready:false, diagram:"soccertennis", description:"Split a 12x24m court into two halves with a low line of cones down the middle. Teams of 2-3 serve the ball to the other side using only volleys or headers -- the receiving side gets one bounce and up to two touches to return it. Score like tennis.", coach_notes:"A great one for encouraging players to enjoy the ball in the air rather than avoiding it. First touch and judging flight and bounce are the real learning points here -- keep it competitive and fun.", progression:"Reduce the touches allowed to one. Make the court narrower to force quicker, more accurate returns." },
  { id:137, title:"Shooting on the Turn",           category:"Attacking", age_groups:["U12","U13","U14"], duration:"15 min", players:"5+",  home_ready:false, diagram:"turnshoot",   description:"Two cones placed 20 yards from goal, about 10 yards apart. Players line up in two groups at the corners. The first player dribbles toward their cone, passes to the inside of it, sprints around the outside, and takes a first-time shot without an extra touch. The next player from the other line starts as soon as the shot is taken.", coach_notes:"Get the hips square to goal quickly as the player comes off the cone -- that's the part that's genuinely hard for this age group. Reward good body shape even when the finish is off target.", progression:"Move the cones further from goal to lengthen the run and shot distance. Switch starting sides so players finish with both feet." },

  // ── GRASSROOTS UK PACK (Sept 2026) ──────────────────────────────────────────
  { id:138, title:"The Cone Weave",                 category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"conesweave",    description:"Set out a line of cones. Navigate through them five different ways in turn: insides of both feet only, outsides of both feet only, right foot only, left foot only, then rollovers (foot over the ball between each cone). 3 runs of each method.", coach_notes:"Don't rush past this one -- it looks basic but it's the foundation everything else builds on. The weaker-foot-only run is usually where the real improvement shows up first.", progression:"Time each method and try to beat last week's score. Reduce the gap between cones to force tighter control." },
  { id:139, title:"Between the Cones",              category:"Strength & Conditioning", age_groups:["U12","U13"],       duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"twoconemoves", description:"Just two cones needed. Move the ball side to side between them using five techniques in sequence: sole-and-inside rolls, sole-and-outside rolls, a figure-of-8 round the front of both cones, a 45-degree V-cut, and an L-drag pulling the ball back and across. 1 minute per move, both feet.", coach_notes:"Get the head up halfway through each minute once the feet start to know what they're doing -- that's the real payoff of this drill, not just the touches.", progression:"Start with just the first two moves for a few weeks, then add the figure-8, V-cut and L-drag once those are comfortable." },
  { id:140, title:"Outside of the Foot Running",    category:"Strength & Conditioning", age_groups:["U12","U13","U14"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"outsiderun",  description:"Two sets of cones close together, joined by a long open arc. Using the outside of one foot only, navigate the first set with close control, accelerate into a sprint through the arc, then come out of the sprint and navigate the second set. Turn and repeat back the other way on the other foot.", coach_notes:"This is really an acceleration and deceleration drill disguised as a ball mastery one -- the change of pace in and out of the sprint is the coaching point, not just the outside-foot touches.", progression:"Increase the length of the arc to test sustained sprint control. Add a defender jogging alongside to add a little pressure." },
  { id:141, title:"Diagonal & Sideways Follow the Pass", category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"5+",  home_ready:false, diagram:"diagsquare",   description:"Mark a square with one player on each corner and two on the starting corner. The first pass goes diagonally and the passer follows it. The receiver takes one touch and can only pass sideways, then also follows. The next player must pass diagonally again, and so on.", coach_notes:"Get them calling the name of who they're passing to before the pass goes -- this is a great arrival drill precisely because it forces communication from the first touch of the session.", progression:"Start slow and let the tempo build naturally as players get comfortable. Add a second ball once the pattern is automatic." },
  { id:142, title:"Pass & Move Square",             category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"movesquare",   description:"Mark a square with cones and scatter a handful of extra flat markers inside it -- more markers than players. Every time a pass is made, everyone except the receiver must shuffle sideways or backwards to a new open marker, keeping their eyes on the ball throughout.", coach_notes:"Great one for the younger end of the group. The constant repositioning teaches players to move off the ball without needing to be told to -- it becomes automatic through repetition.", progression:"Add a defender and set a target of 3-5 completed passes before they can win the ball. If the target is hit, the defender does the press-ups instead of the attackers." },
  { id:143, title:"Long, Short, Switch Rotation",   category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"8-10", home_ready:false, diagram:"threecone",    description:"Three cones -- a 10-yard gap between the first two, a 5-yard gap between the second and third. One player starts on the far cone, the rest queue at the first. Pass, follow the ball to the next cone in the chain, and keep the rotation moving continuously.", coach_notes:"Start slow while players get their control and passing sorted, then let the tempo climb once the pattern is second nature -- rushing it early just breeds sloppy touches.", progression:"Reduce the gaps to sharpen the passing at pace. Add a one-touch condition once players are comfortable with the rotation." },
  { id:144, title:"One-Two Relay Race",             category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"9+",  home_ready:false, diagram:"relayrace",    description:"Split into three teams lined up behind starting cones, with a turning cone set out ahead of each. On the whistle, the first player in each team dribbles to the turning cone, rounds it, and races back. First team to get every player through wins.", coach_notes:"A simple relay, but a great one for a competitive finish to a session -- keep the teams even so it stays close.", progression:"Require left foot out and right foot back (and vice versa for the other side) to make it a technical race, not just a fitness one." },
  { id:145, title:"Passing & Dribbling Awareness",  category:"Passing", age_groups:["U12","U13","U14"], duration:"10 min", players:"8-14", home_ready:false, diagram:"chaosdribble", description:"Two pairs of players stand opposite each other on either side of the penalty area, passing the ball back and forth. Meanwhile, the rest of the squad dribbles freely between them from one side of the area to the other, weaving, doing tricks, going at whatever pace they like. Everyone must keep their head up to avoid colliding with a player or a stray pass.", coach_notes:"It looks and feels like chaos, and it's supposed to. This is the best drill in the pack for curing the head-down running that causes so many turnovers in matches.", progression:"Add cones inside the area so dribblers must bend their runs. Assign left-foot-only passing to some of the passers to add another layer." },
  { id:146, title:"Playing Down the Channels",      category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"channelrun",  description:"A player plays the ball into the channel between a full back and centre back for the centre forward to run onto. The forward can either hold the ball up and lay it back to the player who played it in, or turn and look to cross for the on-rushing midfielders.", coach_notes:"Timing of the run is everything -- too early and the forward is a static target, too late and the ball runs through to the goalkeeper. Walk through the timing at jogging pace before adding real pace.", progression:"Add a tracking defender who must decide whether to go with the run or hold the line. Add a second midfielder making a delayed run to arrive late in the box." },
  { id:147, title:"Linking Play",                   category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"4-6",  home_ready:false, diagram:"linkplay",    description:"The centre forward drops off their marker into a deeper position, receives a pass to feet, takes one touch to lay the ball off to a winger, then spins away and arcs a run to attack the box from the far post for the cross.", coach_notes:"The spin away has to happen the instant the lay-off is played, not a beat later -- that split second is what loses the marking defender.", progression:"Add a second defender tracking the forward's spinning run. Give the winger two cross windows -- early, before the box, or from the byline -- and make them decide which to use." },
  { id:148, title:"Keeping the Ball -- Risk v Retain", category:"Passing", age_groups:["U13","U14"],       duration:"10 min", players:"8-12", home_ready:false, diagram:"riskretain",  description:"Mark a zone just outside the penalty area. One attacker and three defenders must stay inside it; other players can come and go freely. The attacking team starts with 3 'risk points' and loses one every time a pass or dribble inside the zone is lost to a tackle or interception. Score as many goals as possible before the points run out, then swap.", coach_notes:"This puts a real cost on careless possession without shutting the game down completely -- players start weighing up whether a pass is actually on before they play it.", progression:"Let more players move freely in and out of the zone to make it more fluid. Release an extra defender from the zone to increase the pressure." },
  { id:149, title:"Holding Up Play -- The Target Man", category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"targetman",   description:"Centre forward and centre back start just outside the box with a defender on the forward's back. Two wingers and two full backs start on the halfway line. The coach plays the ball to the forward, who must get side-on to the defender, shield the ball with an arm, and receive on the foot furthest from the defender before finding whichever winger has been released.", coach_notes:"Teach the forward to get side-on before the ball arrives, not after -- trying to shield the ball square-on just gets them bullied off it.", progression:"Add a third midfielder and defender so the forward has to scan for a second option. Rotate attackers into the defender's role -- they learn as much from defending it as attacking it." },
  { id:150, title:"Pass, Switch, Finish",           category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-9",  home_ready:false, diagram:"switchfinish", description:"Three starting points with a run of poles or a ladder in front of the middle one. The middle runner drives through the poles; as they reach the end, the ball is switched into their path. They carry on while the two outer runners arc into the box from near and far post for an early cross or a pull-back.", coach_notes:"The timing of the switch pass into the runner's path is the hardest part to get right -- it has to arrive just as they clear the last pole, not before and not after.", progression:"Add a defender to each starting cone, all released the moment the switch pass is played, so the crosser has to read who's losing their marker fastest." },
  { id:151, title:"One-Touch Control & Finish",     category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs", home_ready:false, diagram:"controlfinish", description:"Forward and goalkeeper both start on the goal line and set off together on the whistle. The goalkeeper runs out and back-peddles into goal to reset; the forward runs out to a marker where they receive a pass from the coach, take one touch around the corner, and shoot.", coach_notes:"A heavy first touch is the difference between a clean chance and the keeper smothering it -- reward a good touch even on the reps where the shot doesn't go in.", progression:"Add a defender tracking the forward's run so they must shield the ball between their body and the chasing pressure before shooting." },
  { id:152, title:"Pass, Follow, 1-2 & Finish",     category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"6-8",  home_ready:false, diagram:"onetwofinish", description:"A line of poles or cones leading toward goal. Player 1 plays a firm pass into Player 2 at the first cone, who lays it back first time for a quick 1-2, then Player 1 continues to the next cone while Player 2 spins to receive again. Repeat down the line, finishing with a first-time shot on the last cone.", coach_notes:"Quality of the pass is what makes this flow -- a sloppy first pass breaks the rhythm for the whole sequence, so slow it right down until the passing is clean.", progression:"Increase the distance between cones to demand more accurate passing, or shorten it to raise the tempo. Switch sides so both feet get used." },
  { id:153, title:"Pass, Move, Dribble, Shoot",     category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"twozonedribble", description:"Mark two zones with a defender fixed in each -- they cannot leave their zone. A winger on each side can move the full length between the zones and is limited to three touches if the ball comes to them. The centre forward roams between, looking for the pass or the space created by the wingers combining.", coach_notes:"The forward has to keep changing their mind based on what the defenders do -- reward a player who abandons a 1-2 they'd planned because the defender shifted to block it.", progression:"Add a third zone and defender in the middle to force a longer build-up before the shot." },
  { id:154, title:"One-Touch Finishing -- Call & React", category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"Pairs + passers", home_ready:false, diagram:"mannequincall", description:"Set two mannequins (or standing defenders/coaches) with a coloured cone either side. The shooter starts tucked behind the mannequins, calls for the ball, back-peddles to a central marker, and receives a pass along with a shout of a colour -- they have one touch to set up the shot on that side before finishing.", coach_notes:"Expect the touches to be a bit shapeless the first few times through -- the reaction element is what's being trained here, not the finish itself, so be patient with the early scorelines.", progression:"Call the colour later, right as the ball arrives, to sharpen the reaction window further." },
  { id:155, title:"No Bounce Challenge",            category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"8-14", home_ready:false, diagram:"nobounce",     description:"Rows of cones set out at increasing distance from goal, starting around 6 yards and stepping back every few yards. Split into two teams. Taking turns, a player shoots from the nearest cone -- if the ball hits the net without bouncing first, they move back to the next cone for their next go. One bounce before the net and they're out.", coach_notes:"This rewards clean technique over pure power -- a well-struck, low shot from 18 yards beats a scuffed effort from 9. Keep a leaderboard of who gets furthest back.", progression:"Increase the distance between cones for older age groups. Make it a knockout -- last player standing on each team wins a point." },
  { id:156, title:"Tracking Back & Pressuring the Striker", category:"Tackling", age_groups:["U13","U14"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"channel",    description:"On the whistle, a striker runs a set course around cones toward goal while the goalkeeper back-peddles and sidesteps into position. Once the striker reaches a marked point, the tracking defender sets off in pursuit to close the shot down before it can be taken.", coach_notes:"This builds the habit of the hard sprint back rather than jogging and hoping -- praise the effort of the chase even on reps where the defender doesn't catch up in time.", progression:"Move the defender's starting cone further back to lengthen the chase. Award bonus points for a tackle that also wins possession, not just a block." },
  { id:157, title:"Back Peddling & Controlling the Attacker", category:"Tackling", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs", home_ready:false, diagram:"jockey",     description:"Attacker starts on the halfway line, defender starts between halfway and the edge of the area. Rather than closing the attacker down, the defender back-peddles as they approach, using body position to steer them wide or onto their weaker foot, without attempting a tackle until they reach a marked 'engage line'.", coach_notes:"This teaches control without contact -- many young defenders only know how to engage, not how to delay and shepherd. That patience is a genuinely advanced skill worth starting early.", progression:"Let the goalkeeper call instructions to help the defender read the attacker's options. Move the engage line closer to goal to test composure under more pressure." },
  { id:158, title:"Warm-Up: Shoulder to Shoulder Battle", category:"Tackling", age_groups:["U12","U13","U14"], duration:"10 min", players:"Pairs", home_ready:false, diagram:"shoulderbattle", description:"Two players stand shoulder to shoulder between two cones, backs to goal, leaning into each other to hold their ground. After a few seconds the coach throws the ball over both their heads in a random direction -- both players turn and race to win it and get a shot away before the other can stop them.", coach_notes:"A brilliant pre-match warm-up -- it's competitive, physical and gets players switched on fast. Rotate opponents so everyone gets a few different match-ups.", progression:"Allow rebounds off the goalkeeper to count, adding a second phase to the battle. Give 3 turns each and keep a running score." },
  { id:159, title:"Warm-Up: Crossing & Shooting First Time", category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"8-12", home_ready:false, diagram:"crossfirst", description:"Split into two teams on opposite sides of the pitch. Player 1 from Team A runs around a cone and calls for a cross from Player 1 on Team B, finishing first time before joining the back of Team B's queue. Team B's player then does the same on the other side, and it continues rolling back and forth.", coach_notes:"Continuous and fast-paced -- a great one to open a session with. Focus on body shape as players round the cone, since that's what makes the first-time finish easier on either foot.", progression:"Require every player to have taken at least 2 shots from both sides before the drill ends, ensuring genuine weaker-foot practice." },
  { id:160, title:"Goal Kick Build-Up: Creating the Overload", category:"Tactical", age_groups:["U12","U13"],       duration:"10 min", players:"Full squad", home_ready:false, diagram:"goalkickoverload", description:"For a goal kick, load extra players onto one side of the pitch so the other side is left empty. The centre forward pushes tight onto their marker in the middle. When the defender receives the kick, they take a touch and play into the space created by the overload, where the centre forward -- expecting it -- can win the first contact.", coach_notes:"It only fully works once or twice a game before the opposition wises up, but even then you're left with an overloaded side to exploit -- a genuinely useful pattern for younger groups facing an aggressive press.", progression:"Have the midfielders shift across in support as soon as the overload pass is played, so the move doesn't stall after the first pass." },
  { id:161, title:"Goal Kick Build-Up: Triangles & Facing Play", category:"Tactical", age_groups:["U13","U14"],       duration:"10 min", players:"Full squad", home_ready:false, diagram:"goalkicktriangle", description:"From the goal kick, the keeper plays into the retreating central midfielder's feet. The midfielder either takes a touch or plays first time into a defender, who then has three options depending on how they received it: return the pass to the midfielder now in space, open up to play down the line to the winger, or play safely back to the keeper if the press is too aggressive to risk it.", coach_notes:"The core idea is simple -- always play the way you're facing rather than forcing something difficult under pressure. Pair this with the Heads Up Pass & Move drill so players already understand the front-foot/back-foot control it depends on.", progression:"Introduce a passive presser who reacts a beat after the first pass, so the defender must actually read the pressure rather than assume it." },
  { id:162, title:"Ball Control Box",                category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"Pairs", home_ready:true,  diagram:"controlbox",  description:"Mark a box with four cones. The player stands toward the back of the box while a partner or coach serves five varied balls in turn -- a firm pass to feet, a short high ball, a bouncing ball to the knee, a high ball to the centre of the box, and a chest-height pass. The aim is a clean first touch that stays inside the box every time.", coach_notes:"Vary the serve type genuinely rather than always doing the easy one -- the bouncing and chest serves are usually where the real coaching value is.", progression:"Add a second-touch pass out of the box to a target once the first touch is reliable. Reduce the box size to demand a tighter first touch." },
  { id:163, title:"Multi-Angle Finishing",           category:"Attacking", age_groups:["U12","U13","U14"], duration:"10 min", players:"Any", home_ready:false, diagram:"multiangle", description:"Set up shooting positions at five different spots and angles around the box -- some static, one where the player receives a pass from the coach and has one touch to turn before shooting. Between each shot, the player runs around a cone before moving to the next position.", coach_notes:"Encourage variety in where they aim, not just power down the middle -- and don't skip the final position, since receiving, turning and shooting under a touch limit is the hardest part of the set.", progression:"Add a passive defender closing down on the final position to simulate real pressure on the turn." },
  { id:164, title:"Round-Robin 1v1s",                category:"Attacking", age_groups:["U12","U13"],       duration:"10 min", players:"6+",  home_ready:false, diagram:"1v1box",     description:"Using the penalty area as the pitch, every player takes a turn in a 1v1 against each of the others in the group. Each contest runs for 30 seconds or until a goal is scored, whichever comes first.", coach_notes:"Encourage players to actually try their moves and express themselves rather than just booting the ball long -- the value here is in the attempt, not just the result.", progression:"Reduce the time limit to sharpen decision-making. Restrict the attacker to their weaker foot only for a set of rounds." },
  { id:165, title:"Cross & Finish First Time",       category:"Attacking", age_groups:["U13","U14"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"cross",      description:"Player starts from a marker on the edge of the box, calls for the ball as they run in, and must finish first time from the coach's cross. Deliveries from the left are finished with the right foot, deliveries from the right with the left, building genuine both-footed finishing rather than favouring the strong side.", coach_notes:"No second touch allowed -- if the first touch isn't a shot, it doesn't count. This keeps the focus on genuine first-time finishing rather than a controlled effort.", progression:"Vary the delivery -- driven, floated, pulled back -- so the first-time technique has to adapt each time rather than becoming a single repeated action." },

  { id:166, title:"Circle Keep-Away: Swap or Shame", category:"Passing", age_groups:["U12","U13"],       duration:"10 min", players:"6-10", home_ready:false, diagram:"rondo",      description:"Mark a 10-yard circle with two defenders inside, each holding a coloured bib in their hand. The group outside keeps possession, first pass free. The moment a defender wins the ball, they swap immediately -- dropping the bib for the player who lost it to pick up and become the new defender. A misplaced pass or a heavy touch that runs out of the circle does the same. If the attackers string together 10 passes without losing it, both defenders have to do a lap around the outside of the circle before coming back in.", coach_notes:"The 'lap of shame' is what makes this one of the most requested games in the session -- a nice reward drill after a week of grinding through straight Rondo work rather than something to run every session.", progression:"Shrink the circle to sharpen decision-making under pressure. Add a third defender for older or more advanced groups." },

  // ── FUNDAMENTALS (development group) ────────────────────────────────────────
  { id:167, title:"Inside-of-the-Foot Pass Technique", category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"basicpass",   description:"The foundation of every pass in the game. Non-kicking foot plants level with the ball, pointing at the target. Ankle locked firm, strike the dead centre of the ball with the inside of the foot, then follow through toward the target. Walk through the stance with no ball first, then add the ball at a standstill before any movement is involved.", coach_notes:"This is the one to slow right down for -- resist the urge to let a player just 'have a go' before the stance is right. A good non-kicking foot position fixes most passing problems before the kicking foot even swings.", progression:"Once the stance is consistent, add a partner 5 yards away and pass back and forth. Only increase the distance once accuracy is reliable at close range." },
  { id:168, title:"Toe vs Laces vs Inside",            category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"footparts",   description:"Three cones in a row, all the same distance away. Strike the ball at the first cone with the toe, the second with the laces (top of the foot), and the third with the inside of the foot. Talk through what each contact felt like and how the ball behaved differently each time.", coach_notes:"Most technique problems come from players not knowing which part of the foot they just used. Making the comparison explicit, out loud, speeds up the learning enormously.", progression:"Once the difference is clear, explain when each is actually used in a game -- inside for accuracy, laces for power and shooting, toe rarely on purpose." },
  { id:169, title:"Cushioning the Ball",               category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"cushion",     description:"A parent or coach rolls or gently tosses the ball to the player. Instead of letting it bounce away, the player relaxes the receiving foot (or thigh or chest for higher balls) at the moment of contact to cushion it dead, rather than stiffly blocking it.", coach_notes:"The single biggest giveaway of a weaker first touch is a stiff, flat foot on contact. Get them to imagine 'catching' the ball with their foot rather than stopping it.", progression:"Increase the pace and height of the serve gradually. Once comfortable, add a second touch to move the ball away from an imaginary defender." },
  { id:170, title:"Stand on It",                       category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"standonit",   description:"As simple as it sounds: roll the ball a short distance and bring it to a complete stop under the sole of the foot before moving on. No fancy footwork, just stopping the ball dead, every time, from different speeds and angles.", coach_notes:"Don't skip this one just because it looks too easy -- plenty of players who can already do flashy tricks still can't reliably stop a ball dead under pressure. This builds that base layer.", progression:"Increase the speed and randomness of the roll. Progress to stopping with the weaker foot only." },
  { id:171, title:"Short Pass & Target",               category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"shorttarget", description:"Two cones or a small target just 3-4 yards apart. Simple, repeated passing at very close range with no pressure and no decision-making required -- just groove the technique through pure repetition. 10 passes each foot.", coach_notes:"Keep the distance genuinely short -- the temptation is always to make it harder too soon. The point is enough reps at an easy distance that the technique becomes automatic before adding any real challenge.", progression:"Once consistent, increase the distance in small steps of a yard at a time. Introduce a one-touch return once accuracy is solid." },
  { id:172, title:"Receiving Across the Body",         category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Pairs",                home_ready:false, diagram:"openbody",    description:"Player stands side-on rather than facing the passer directly. As the ball arrives, they take the touch across their body rather than straight back the way it came, opening up their stance to see more of the pitch.", coach_notes:"This is a genuinely harder habit to build than it looks, since most players' instinct is to simply stop the ball directly in front of them. Walk it through at a standstill before adding any pace.", progression:"Add a second player standing where the first touch should be aimed, so there's a real target to open up towards. Add light passive pressure once the habit is forming." },
  { id:173, title:"Rolling & Stopping",                category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true, diagram:"rollstop",    description:"Push the ball a few steps forward with the inside of the foot, then stop it dead with the sole before pushing it on again. Keep the touches close and controlled rather than kicking the ball away and chasing after it.", coach_notes:"This is the very first building block of dribbling -- the push-and-stop rhythm underneath everything more advanced that comes later. Little and often, ideally every session.", progression:"Once comfortable, add gentle changes of direction between pushes. Progress to using the weaker foot only." },

  // ── FUNDAMENTALS: WEAKER FOOT ────────────────────────────────────────────────
  { id:174, title:"Weak Foot Wall Rebounds",      category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"wall",       description:"Exactly the same as a normal wall pass, but every touch -- the pass and the controlling touch on the rebound -- is with the weaker foot only, no swapping back to the strong foot even when a touch goes wrong.", coach_notes:"Resist the urge to let them switch back when it feels clumsy -- the discomfort is the whole point, and it fades fast with repetition.", progression:"Once comfortable at a standstill, add a short approach run before the pass. Increase the distance from the wall gradually." },
  { id:175, title:"Just Touches: Weak Foot Only", category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo",                  home_ready:true,  diagram:"weaktouch",  description:"No movement, no passing, nothing to get right or wrong. Simply stand over the ball and tap it lightly from side to side using only the weaker foot, getting the foot used to the feel of the ball. 3 sets of 30 seconds.", coach_notes:"This is deliberately the lowest-pressure weak-foot drill in the pack -- there's genuinely nothing to fail at, which makes it a good entry point for a player who's self-conscious about their weaker foot.", progression:"Once comfortable, add small forward and backward taps alongside the side-to-side ones. Progress to Stand on It and Rolling & Stopping using the weaker foot only." },
  { id:176, title:"Strong Receive, Weak Pass",    category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Pairs",                home_ready:false, diagram:"bridgefoot", description:"Player A passes to Player B, who controls the ball with their strong foot as normal, then immediately plays the next pass using only their weaker foot. This bridges the gap between full weak-foot isolation and normal play.", coach_notes:"A gentler starting point than going fully weak-foot for everything -- it isolates just the pass itself rather than the touch and the pass together, which some players find a less overwhelming place to start.", progression:"Once comfortable, reverse it -- control with the weak foot, pass with the strong foot. Eventually combine both halves using the weak foot only." },
  { id:177, title:"Weak Foot Target Count",       category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"shorttarget", description:"Same short-range target setup as Short Pass & Target, but every pass is with the weaker foot only and the player counts how many out of 10 hit the target cleanly. Record the score and try to beat it next time.", coach_notes:"It's completely normal for this score to be noticeably lower than the strong-foot version at first -- that gap is useful information, not a problem, and it closes quickly with regular reps.", progression:"Once the score matches the strong-foot version at this distance, increase the distance slightly and start the count again." },
  { id:178, title:"Weak Foot Rolling & Stopping", category:"Fundamentals", age_groups:["U12","U13","U14","U15"], duration:"10 min", players:"Solo or with a parent", home_ready:true,  diagram:"rollstop",   description:"The same push-and-stop sequence as Rolling & Stopping, but performed entirely with the weaker foot -- push the ball a few steps forward, stop it dead under the sole, and push it on again.", coach_notes:"Keep the touches small and controlled rather than letting the ball run away, just like the strong-foot version -- the instinct to rush through weak-foot work usually makes the technique worse, not better.", progression:"Once comfortable, add gentle changes of direction between pushes, exactly as in the strong-foot version." },

]